        return new LoanView(loan.loanKey(), loan.evidenceKey(), loan.custodianId(),
                loan.borrowerId(), loan.purpose(), loan.status(), loan.loanedAt(), loan.dueAtUtc(),
                overdue, loan.returnedAt(), loan.sealIntact(), loan.returnNote());
    }
}

