    if (!dueInstant.isAfter(nowInstant)) {
        throw ApiException.badRequest("UTC 应还时刻必须晚于服务端当前时刻");
    }
    if (dueInstant.isAfter(nowInstant.plus(MAX_LOAN_DURATION))) {
        throw ApiException.badRequest("UTC 应还时刻距当前时刻不得超过 72 小时");
